#!/usr/bin/env python3
"""Verify external math-library selection and retain old downloaded sources."""
from pathlib import Path
import os
import subprocess
import sys


GCC_REVISION = "04696df09633baf97cdbbdd6e9929b9d472161d3"
# Names generated by contrib/download_prerequisites at that exact revision.
GENERATED = {
    "gmp": "gmp-6.2.1",
    "mpfr": "mpfr-4.1.0",
    "mpc": "mpc-1.2.1",
    "isl": "isl-0.24",
}


def prepare_external_math(root: Path) -> None:
    root = root.resolve(strict=True)
    if not (root / ".socdaml-native-v1").is_file():
        raise SystemExit("Not a prepared SoCDAML native workspace.")
    build = root / "build/riscv"
    log_lines = set((build / "config.log").read_text().splitlines())
    for result in (
        "ac_cv_lib_gmp___gmpz_init=yes",
        "ac_cv_lib_mpfr_mpfr_init=yes",
        "ac_cv_lib_mpc_mpc_init2=yes",
    ):
        if result not in log_lines:
            raise SystemExit(f"Host library detection did not pass: {result}. See {build / 'config.log'}")
    makefile = (build / "Makefile").read_text()
    anchor = "stamps/build-gcc-newlib-stage1:"
    if makefile.count(anchor) != 1:
        raise SystemExit("Unexpected toolchain Makefile; cannot verify dependency selection.")
    recipe = makefile.split(anchor, 1)[1].split("\n\n", 1)[0]
    guard = 'test "false" = "true"; then cd $< && ./contrib/download_prerequisites; fi'
    if guard not in recipe:
        raise SystemExit("GCC prerequisite download is still enabled; stopping before make.")
    print("PASS: top-level configure found GMP/MPFR/MPC; prerequisite download is disabled.")

    gcc = root / "deps/riscv-gnu-toolchain/gcc"
    active = [name for name in GENERATED if os.path.lexists(gcc / name)]
    if not active:
        print("PASS: no active in-tree math-library source aliases.")
        return
    revision = subprocess.check_output(
        ["git", "-C", str(gcc), "rev-parse", "HEAD"], text=True
    ).strip()
    if revision != GCC_REVISION:
        raise SystemExit("Unexpected GCC revision; refusing to move dependency aliases.")
    moves = []
    # Validate every candidate before changing any path. Never move directories,
    # unknown symlinks or existing backups, and never delete downloaded sources.
    for name in active:
        alias = gcc / name
        expected = GENERATED[name]
        if not alias.is_symlink() or os.readlink(alias) not in (
            expected, expected + "/", "./" + expected, "./" + expected + "/"
        ):
            raise SystemExit(f"Unexpected dependency path; retained unchanged: {alias}")
        backup = gcc / (".socdaml-homebrew-disabled-" + name)
        if os.path.lexists(backup):
            raise SystemExit(f"Alias backup already exists; retained unchanged: {backup}")
        moves.append((alias, backup))
    for alias, backup in moves:
        alias.rename(backup)
        print(f"Retained generated alias as {backup.name}; downloaded source is unchanged.")


if __name__ == "__main__":
    if len(sys.argv) != 2:
        raise SystemExit("Usage: toolchain_math.py NATIVE_DIRECTORY")
    prepare_external_math(Path(sys.argv[1]))
